template<class T>
bool std::atomic_compare_exchange_weak(std::atomic<T>* obj, T* expected, T desired, std::memory_order success_order = std::memory_order_seq_cst, std::memory_order failure_order = std::memory_order_seq_cst);
// Implementation notes: 'obj' must be a pointer to an atomic object; 'expected' is the value to compare against; 'desired' is the value to store if the comparison succeeds. The success_order applies if the exchange happens, while failure_order applies if it doesn't. Compilers like GCC or Clang use built-in functions (e.g., __atomic_compare_exchange) to map this to hardware instructions, ensuring atomicity and ordering.
